/* Meal photos, keyed by data-photo. Loaded by index.html. Second store, added Oct 24. */
(function(){var P={
 "oct24-1": "data:image/jpeg;base64,",
 "oct24-2": "data:image/jpeg;base64,"
};
function go(){document.querySelectorAll("img[data-photo]").forEach(function(i){var d=P[i.getAttribute("data-photo")];if(d)i.src=d;});}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",go);else go();})();
